library(creditratingsystem)
target<-list(exposure_id='facility',horizon=1,time_unit='years',probability_measure='PHYSICAL',conditioning='performing')
risks<-function(p=.1,event=.2,failure=.5,success=0)list(base=list(stage='PRE_TRANSFER',pd=p,target=target,applied_effects=list()),transfer=transfer_event_default_probability(event,failure,list(effect_id='liquidity',success_probability_given_event_and_unmitigated_failure=success,conditioning='event_and_unmitigated_failure',assumption_reference='synthetic-tree'),event_id='freeze',target=target))
reject<-function(expr,code=NULL){e<-tryCatch({force(expr);NULL},error=identity);stopifnot(inherits(e,'creditratingsystem_error'));if(!is.null(code))stopifnot(identical(code,e$code))}
for(row in list(c(0,0,0),c(1,0,.2),c(.5,0,.1),c(.5,.6,.04),c(.5,1,0))){r<-risks(failure=row[1],success=row[2])$transfer$value;stopifnot(abs(r$probability-row[3])<1e-15,abs(r$unmitigated_default_probability-r$probability-r$mitigated_default_mass)<1e-15)}
r<-risks();u<-combine_default_transfer(r$base,r$transfer,'independent');stopifnot(abs(u$value$combined_pd-.19)<1e-15,max(abs(unlist(u$value$exclusive_probabilities)-c(.81,.09,.09,.01)))<1e-15)
nested<-combine_default_transfer(r$base,r$transfer,'explicit',.1);stopifnot(nested$value$combined_pd==.1,nested$value$exclusive_probabilities$default_only==0)
bad<-nested$value;bad$pd<-.1;reject(combine_default_transfer(bad,r$transfer,'independent'),'TRANSFER_DOUBLE_COUNT')
for(j in c(-.01,.11,.8))reject(combine_default_transfer(r$base,r$transfer,'explicit',j))
losses<-list(neither=0,default_only=60,transfer_only=20,joint=70)
stopifnot(abs(transfer_loss_components(u,losses,'EUR',list())$value$expected_loss-7.9)<1e-14)
reject(transfer_loss_components(u,losses,'EUR',list('liquidity')),'TRANSFER_DOUBLE_COUNT')
r<-risks(event=0);u<-combine_default_transfer(r$base,r$transfer,'explicit',0);stopifnot(transfer_loss_components(u,losses,'EUR',list())$value$expected_loss==6)
payment<-list(payment_id='p',due_at='2024-06-01',known_at='2024-01-01',currency='EUR',source_currency='EUR',payer_jurisdiction='A',payee_jurisdiction='B',payment_jurisdictions=list('A','B'))
event<-list(event_id='freeze',event_type='PAYMENT_FREEZE',jurisdictions=list('A'),currencies=list('EUR'),effective_from='2024-01-01',known_at='2024-01-01',exemptions=list(list(payment_id='p',reason='licensed',evidence_reference='license',known_at='2024-03-01')))
policy<-list(policy_id='policy',version='1',events=list(event))
a<-assess_transfer_applicability(list(payment),policy,'2024-01-01','2024-02-01','2024-12-31');b<-assess_transfer_applicability(list(payment),policy,'2024-01-01','2024-03-01','2024-12-31')
stopifnot(a$value$payments[[1]]$status=='APPLICABLE',b$value$payments[[1]]$status=='EXEMPT')
policy$events[[1]]$event_type<-'CONVERSION_RESTRICTION';stopifnot(assess_transfer_applicability(list(payment),policy,'2024-01-01','2024-02-01','2024-12-31')$value$payments[[1]]$status=='NO_MATCHING_EVENT')
payment$payment_jurisdictions<-NULL;stopifnot(assess_transfer_applicability(list(payment),policy,'2024-01-01','2024-02-01','2024-12-31')$value$payments[[1]]$status=='INSUFFICIENT_INFORMATION')
